glsl4.vert:
precision highp float;
layout(set = 0, binding = 1) uniform CCCamera {
  highp   mat4 cc_matView;
  highp   mat4 cc_matViewInv;
  highp   mat4 cc_matProj;
  highp   mat4 cc_matProjInv;
  highp   mat4 cc_matViewProj;
  highp   mat4 cc_matViewProjInv;
  highp   vec4 cc_cameraPos;
  mediump vec4 cc_surfaceTransform;
  mediump vec4 cc_screenScale;
  mediump vec4 cc_exposure;
  mediump vec4 cc_mainLitDir;
  mediump vec4 cc_mainLitColor;
  mediump vec4 cc_ambientSky;
  mediump vec4 cc_ambientGround;
  mediump vec4 cc_fogColor;
  mediump vec4 cc_fogBase;
  mediump vec4 cc_fogAdd;
  mediump vec4 cc_nearFar;
  mediump vec4 cc_viewPort;
};
layout(set = 2, binding = 0) uniform CCLocal {
  highp mat4 cc_matWorld;
  highp mat4 cc_matWorldIT;
  highp vec4 cc_lightingMapUVParam;
  highp vec4 cc_localShadowBias;
};
layout(set = 1, binding = 0) uniform Constants {
  vec4 wave;
  vec4 eye;
  vec4 channels;
  vec4 optics;
  mat4 reflectionVP;
  mat4 refractionVP;
  mat4 inverseRefractionVP;
  vec4 impact;
};
layout(location = 0) in vec3 a_position;
out highp vec3 waterPosition;
out highp vec3 waterNormal;
out highp vec4 reflectedClip;
out highp vec4 refractedClip;
// Three deterministic gravity waves, shared by displacement and caustics.
// Return height and analytic x/z derivatives; amplitude is in world units.
vec3 waveField(vec2 p) {
    vec2 d0 = normalize(vec2(1.0, 0.35));
    vec2 d1 = normalize(vec2(-0.4, 1.0));
    vec2 d2 = normalize(vec2(0.8, -0.6));
    float a = wave.x;
    float s0 = dot(p, d0) * 1.7 + wave.y * 1.25 + wave.z;
    float s1 = dot(p, d1) * 2.8 - wave.y * 1.65 + wave.z * 0.73;
    float s2 = dot(p, d2) * 5.1 + wave.y * 2.15 + wave.z * 1.37;
    float h = a * (sin(s0) + 0.48 * sin(s1) + 0.18 * sin(s2));
    vec2 g = a * (1.7 * cos(s0) * d0 + 1.344 * cos(s1) * d1 + 0.918 * cos(s2) * d2);
    vec2 delta = p - impact.xy;
    float radius = max(length(delta), 0.0001);
    float age = max(wave.y - impact.z, 0.0);
    float ring = radius - 0.15 - age * 1.4;
    float envelope = impact.w * 0.085 * exp(-ring * ring * 35.0 - age * 1.6);
    float phase = radius * 22.0 - age * 8.0;
    h += envelope * sin(phase);
    g += delta / radius * envelope * (22.0 * cos(phase) - 70.0 * ring * sin(phase));
    vec2 cell = floor(p / 1.6);
    vec2 rainDelta = p - (cell + 0.5) * 1.6;
    float rainR = max(length(rainDelta), 0.0001);
    float rainAge = fract(wave.y * 0.85 + sin(dot(cell, vec2(12.73, 45.91))) * 437.1);
    float rainRing = rainR - rainAge * 0.85;
    float rainEnvelope = wave.w * 0.026 * exp(-rainRing * rainRing * 55.0 - rainAge * 1.4);
    h += rainEnvelope * sin(rainR * 26.0 - rainAge * 9.0);
    g += rainDelta / rainR * rainEnvelope * (26.0 * cos(rainR * 26.0 - rainAge * 9.0) - 110.0 * rainRing * sin(rainR * 26.0 - rainAge * 9.0));
    return vec3(h, g);
}

void main() {
    vec4 world = cc_matWorld * vec4(a_position, 1.0);
    vec3 field = waveField(world.xz);
    world.y += field.x;
    waterNormal = normalize(vec3(-field.y, 1.0, -field.z));
    waterPosition = world.xyz;
    reflectedClip = reflectionVP * world;
    refractedClip = refractionVP * world;
    gl_Position = cc_matViewProj * world;
}

glsl4.frag:
precision highp float;
layout(set = 0, binding = 0) uniform CCGlobal {
  highp   vec4 cc_time;
  mediump vec4 cc_screenSize;
  mediump vec4 cc_nativeSize;
  mediump vec4 cc_debug_view_mode;
};
layout(set = 1, binding = 0) uniform Constants {
  vec4 wave;
  vec4 eye;
  vec4 channels;
  vec4 optics;
  mat4 reflectionVP;
  mat4 refractionVP;
  mat4 inverseRefractionVP;
  vec4 impact;
};
layout(set = 1, binding = 1) uniform sampler2D reflectionMap;
layout(set = 1, binding = 2) uniform sampler2D refractionMap;
layout(set = 1, binding = 3) uniform sampler2D depthMap;
in highp vec3 waterPosition;
in highp vec3 waterNormal;
in highp vec4 reflectedClip;
in highp vec4 refractedClip;
layout(location = 0) out vec4 cc_FragColor;
void main() {
    vec3 n = normalize(waterNormal);
    vec3 view = normalize(eye.xyz - waterPosition);
    vec2 refractUV = refractedClip.xy / refractedClip.w * 0.5 + 0.5;
    vec2 reflectUV = reflectedClip.xy / reflectedClip.w * 0.5 + 0.5;
    vec2 perturbation = n.xz * optics.x;
    refractUV = clamp(refractUV + perturbation, vec2(0.003), vec2(0.997));
    reflectUV = clamp(reflectUV + perturbation, vec2(0.003), vec2(0.997));
    float depth = texture(depthMap, refractUV).r;
    // WebGL2 depth buffer [0,1] -> clip z [-1,1], including the oblique projection.
    vec4 receiver = inverseRefractionVP * vec4(refractUV * 2.0 - 1.0, depth * 2.0 - 1.0, 1.0);
    vec3 bottom = receiver.xyz / receiver.w;
    float thickness = depth >= 0.999999 ? 8.0 : clamp(length(bottom - waterPosition), 0.0, 8.0);
    vec3 transmitted = texture(refractionMap, refractUV).rgb;
    vec3 reflected = texture(reflectionMap, reflectUV).rgb;
    vec3 absorption = exp(-vec3(0.32, 0.10, 0.065) * thickness * optics.y * channels.z);
    vec3 underwater = transmitted * absorption + vec3(0.025, 0.24, 0.28) * (1.0 - absorption);
    float fresnel = 0.0204 + 0.9796 * pow(1.0 - max(dot(n, view), 0.0), 5.0);
    vec3 color = mix(vec3(0.035, 0.28, 0.31), underwater, channels.y);
    color = mix(color, reflected, fresnel * channels.x);
    vec3 halfVector = normalize(view + normalize(vec3(-0.4, 0.9, 0.3)));
    color += vec3(1.0, 0.91, 0.72) * pow(max(dot(n, halfVector), 0.0), 110.0) * 0.35;
    float foam = (1.0 - smoothstep(0.06, 0.35, thickness)) * channels.z;
    color = mix(color, vec3(0.78, 0.92, 0.93), foam * 0.55);
    cc_FragColor = vec4(color, 1.0);
}

